#!/usr/bin/env python3
"""Parity guard — generated by `/parity guard`. Edit the contract, not this file.

Checks THIS repository against ITS OWN copy of the parity contract. It never
reads another platform's sources, needs no sibling checkout, and has no
dependencies beyond the standard library, so it runs identically on a developer
machine and in a clean CI container.

It FAILS when it cannot do its job. A guard that skips itself when the inputs
are missing reports green while verifying nothing, which is worse than having
no guard at all: it teaches everyone that the check passed.

    python3 parity/guard.py            # from the repository root
    python3 parity/guard.py --platform ios
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import sys
from pathlib import Path

PLATFORM = "@PLATFORM@"

STRINGS_GLOBS = ["**/res/values/strings.xml", "**/*.xcstrings", "**/*.strings",
                 "**/*.arb", "**/locales/**/*.json", "**/i18n/**/*.json"]
CONTRACT_FILES = ("pair.json", "features.json", "strings.json", "telemetry.json")
LOCK_NAME = "CONTRACT.lock"
# Restated from the tool's own rule, because this file must stay dependency-free.
# The tool's selftest cross-checks the two so they cannot drift apart.
MEMBER_DIRS = (("fixtures", "*.json"), ("use-cases", "*.md"))
PRUNE = {
    ".git", ".gradle", ".idea", "build", "out", "dist", "node_modules", "Pods",
    "DerivedData", ".build", "xcuserdata", ".venv", "__pycache__", ".dart_tool",
}
SOURCE_SUFFIXES = (".swift", ".kt", ".java", ".dart", ".ts", ".tsx", ".js", ".jsx", ".m", ".mm")


def fail(message: str) -> None:
    print(f"parity guard: FAIL {message}")
    FAILURES.append(message)


FAILURES: list[str] = []


def read_json(path: Path) -> dict:
    if not path.exists():
        raise SystemExit(f"parity guard: cannot run — missing {path}")
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as error:
        raise SystemExit(f"parity guard: cannot run — malformed {path}: {error}")


def glob_matches(pattern: str, path: str) -> bool:
    regex, index = ["^"], 0
    while index < len(pattern):
        if pattern.startswith("**/", index):
            regex.append("(?:.*/)?")
            index += 3
        elif pattern.startswith("**", index):
            regex.append(".*")
            index += 2
        elif pattern[index] == "*":
            regex.append("[^/]*")
            index += 1
        elif pattern[index] == "?":
            regex.append("[^/]")
            index += 1
        else:
            regex.append(re.escape(pattern[index]))
            index += 1
    regex.append("$")
    return re.match("".join(regex), path) is not None


def walk(root: Path) -> list[str]:
    found: list[str] = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = sorted(d for d in dirnames if d not in PRUNE and not d.endswith(".xcodeproj"))
        for name in filenames:
            found.append(Path(dirpath, name).relative_to(root).as_posix())
    return sorted(found)


def contract_members(base) -> list[str]:
    """Every file the contract consists of, relative to `parity/`."""
    base = Path(base)
    members = [name for name in CONTRACT_FILES if (base / name).exists()]
    for directory, pattern in MEMBER_DIRS:
        root = base / directory
        if root.is_dir():
            members += [path.relative_to(base).as_posix() for path in root.rglob(pattern)]
    return sorted(members)


def check_lock(base: Path) -> None:
    """The copy in this repo must be the bytes the lock recorded."""
    lock = read_json(base / LOCK_NAME)
    recorded = lock.get("files", {})
    if not recorded:
        raise SystemExit(f"parity guard: cannot run — {LOCK_NAME} records no files")
    for name, digest in sorted(recorded.items()):
        path = base / name
        if not path.exists():
            fail(f"contract file recorded in the lock is gone: {name}")
            continue
        actual = hashlib.sha256(path.read_bytes()).hexdigest()
        if actual != digest:
            fail(f"contract file edited by hand: {name} (run `/parity sync`)")
    for name in sorted(set(contract_members(base)) - set(recorded)):
        fail(f"contract file not covered by the lock: {name} (run `/parity sync`)")


def test_evidence(root: Path, files: list[str]) -> dict[str, str]:
    """Test-suite name -> that file's text, for the suites this repo actually has."""
    return {
        Path(rel).stem: (root / rel).read_text(encoding="utf-8", errors="replace")
        for rel in files
        if rel.endswith(SOURCE_SUFFIXES)
    }


def check_own_criteria(base: Path, root: Path, files: list[str], platform: str) -> None:
    """Every criterion this platform owns needs the test evidence the contract names.

    Evidence, not location: a criterion is satisfied here when a test that
    exercises it exists, wherever the implementation happens to live. Checking
    file paths instead would turn an ordinary refactor — or simply organising
    this platform the way its ecosystem does — into a red build.
    """
    features = read_json(base / "features.json")
    suites = test_evidence(root, files)
    for feature in features.get("features", []):
        deviated = {
            criterion
            for deviation in feature.get("deviations", [])
            if deviation.get("platform") == platform
            for criterion in (deviation.get("criteria") or ["*"])
        }
        for criterion in feature.get("criteria", []):
            if "*" in deviated or criterion["id"] in deviated:
                continue
            owner = criterion.get("owners", {}).get(platform)
            if owner is None or owner.get("status") == "missing":
                continue
            label = f"{feature['id']}/{criterion['id']}"
            named = owner.get("tests", [])
            if not named:
                fail(f"{label}: implemented here but the contract names no test as evidence")
            for reference in named:
                suite, _, case = reference.partition("#")
                if suite not in suites:
                    fail(f"{label}: test suite '{suite}' named by the contract does not exist")
                elif case and case not in suites[suite]:
                    fail(f"{label}: test case '{case}' is not in '{suite}'")
            doc = criterion.get("doc")
            if doc and not (base / doc).exists():
                fail(f"{label}: contract references a doc this repo does not have: {doc}")
        for fixture in feature.get("fixtures", []):
            if not (base / fixture).exists():
                fail(f"{feature['id']}: fixture missing from this repo: {fixture}")


def check_own_resources(base: Path, root: Path, files: list[str], platform: str, pair: dict) -> None:
    """Resources this platform owes the contract must exist here.

    This is the half of a strings check that belongs in a repository. The other
    half — that the platforms agree — belongs to the tool, not to a test suite,
    because no repo should need a sibling checkout to go green.

    Strings are matched by parsed identity, never by searching the file for the
    identifier's text. In an `.xcstrings` catalog the identifier *is* the
    English sentence, so a substring search answers "does this text appear
    anywhere" — and a deleted key whose text is a prefix of a longer key that
    survives comes back present. That false pass is silent and data-dependent,
    which is the worst shape a check can have.

    Telemetry stays on a substring search on purpose: event names are referenced
    from source code, not declared in a catalog, so there is no identity to parse.
    """
    config = pair.get("platforms", {}).get(platform, {})
    for axis, filename, defaults in (
        ("strings", "strings.json", STRINGS_GLOBS),
        ("telemetry", "telemetry.json", config.get("telemetry", {}).get("paths", [])),
    ):
        path = base / filename
        if axis not in pair.get("axes", []) or not path.exists():
            continue
        globs = config.get(f"{axis}_paths") or defaults
        matched = [rel for rel in files if any(glob_matches(pattern, rel) for pattern in globs)]
        if not matched:
            fail(f"{axis}: no source file here matches {globs}, so nothing can be verified")
            continue
        texts = [(rel, (root / rel).read_text(encoding="utf-8", errors="replace")) for rel in matched]
        defined: set[str] = set()
        haystack = ""
        if axis == "strings":
            for rel, text in texts:
                defined |= declared_resources(text, rel)
            if not defined:
                fail(f"{axis}: {matched} parsed to no identifiers, so nothing can be verified")
                continue
        else:
            haystack = "\n".join(text for _, text in texts)
        table = read_json(path).get({"strings": "keys", "telemetry": "events"}[axis], {})
        for neutral, mapping in sorted(table.items()):
            resource = mapping.get(platform)
            if resource is None:
                continue
            found = (resource in defined) if axis == "strings" else bool(
                re.search(rf"(?<![\w.]){re.escape(resource)}(?![\w.])", haystack))
            if not found:
                fail(f"{axis}: '{neutral}' maps to '{resource}', which is not defined here")


def declared_resources(text: str, rel: str) -> set[str]:
    """The identifiers a catalog actually defines, parsed rather than grepped.

    Substring matching cannot answer this question. In an `.xcstrings` catalog
    the identifier *is* the English sentence, so a key that has been deleted
    still appears in the file as the value of its own translations — and a
    grep-based check reports it as present. That false negative is the reason
    this reads the formats instead.
    """
    if rel.endswith(".xcstrings"):
        try:
            entries = json.loads(text).get("strings", {})
        except json.JSONDecodeError:
            return set()
        # `shouldTranslate: false` marks a string that needs no translation —
        # a brand name, a metric abbreviation, a format passthrough. Those are
        # still declared resources. The empty key is not: Xcode records it as
        # an artifact, and no platform can be held to it.
        return {k for k in entries if k}
    if rel.endswith(".xml"):
        return set(re.findall(r'<(?:string|plurals|string-array)\s+name="([^"]+)"', text))
    if rel.endswith(".strings"):
        return set(re.findall(r'^\s*"((?:[^"\\]|\\.)*)"\s*=', text, re.MULTILINE))
    return set()


def check_undeclared_resources(base: Path, root: Path, files: list[str], platform: str,
                               pair: dict) -> None:
    """Catalog entries this repo defines that the contract has never heard of.

    This is a statement about one repository, so it belongs here and needs no
    sibling: a key added on one platform and mapped nowhere is how two catalogs
    drift apart while both builds stay green.
    """
    path = base / "strings.json"
    if "strings" not in pair.get("axes", []) or not path.exists():
        return
    config = pair.get("platforms", {}).get(platform, {})
    globs = config.get("strings_paths") or STRINGS_GLOBS
    ignore = tuple(config.get("strings_ignore") or ())
    declared = {
        mapping[platform]
        for mapping in read_json(path).get("keys", {}).values()
        if isinstance(mapping.get(platform), str)
    }
    for rel in files:
        if not any(glob_matches(pattern, rel) for pattern in globs):
            continue
        found = declared_resources((root / rel).read_text(encoding="utf-8", errors="replace"), rel)
        for name in sorted(found - declared):
            if name.startswith(ignore):
                continue
            fail(f"strings: '{name}' is defined in {rel} but the contract does not declare it")


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--platform", default=PLATFORM)
    parser.add_argument("--root", type=Path, default=Path(__file__).resolve().parent.parent)
    args = parser.parse_args(argv)

    root = args.root.resolve()
    base = root / "parity"
    platform = args.platform
    if platform.startswith("@"):
        raise SystemExit("parity guard: cannot run — no platform baked in; pass --platform")

    pair = read_json(base / "pair.json")
    if platform not in pair.get("platforms", {}):
        raise SystemExit(f"parity guard: cannot run — '{platform}' is not declared in pair.json")

    files = walk(root)
    check_lock(base)
    check_own_criteria(base, root, files, platform)
    check_own_resources(base, root, files, platform, pair)
    check_undeclared_resources(base, root, files, platform, pair)

    if FAILURES:
        print(f"\nparity guard: {len(FAILURES)} failure(s) for platform '{platform}'")
        return 1
    print(f"parity guard: ok — platform '{platform}' satisfies its side of the contract")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
